// Lishaq Solutions — minimal interactions
(function () {
  // Mobile nav
  const toggle = document.querySelector('.menu-toggle');
  const links = document.querySelector('.nav-links');
  if (toggle && links) {
    toggle.addEventListener('click', () => links.classList.toggle('open'));
  }

  // Active link - Fixed for GitHub Pages
  const currentPath = window.location.pathname;
  
  document.querySelectorAll('.nav-links a').forEach((a) => {
    const href = a.getAttribute('href');
    
    // Remove any existing active class
    a.classList.remove('active');
    
    // Case 1: Homepage
    if (href === '/lishaqsolutions/' || href === '/lishaqsolutions') {
      if (currentPath === '/lishaqsolutions/' || 
          currentPath === '/lishaqsolutions' || 
          currentPath === '/lishaqsolutions/index.html' ||
          currentPath === '/') {
        a.classList.add('active');
      }
    }
    // Case 2: Other pages - check if the link href matches the current path
    else {
      // Remove trailing slash for comparison if needed
      const cleanHref = href.endsWith('/') ? href.slice(0, -1) : href;
      const cleanPath = currentPath.endsWith('/') ? currentPath.slice(0, -1) : currentPath;
      
      if (cleanHref === cleanPath) {
        a.classList.add('active');
      }
      // For sub-pages like /lishaqsolutions/services/pos-system/
      else if (cleanPath.startsWith(cleanHref) && cleanHref !== '/lishaqsolutions') {
        a.classList.add('active');
      }
    }
  });

  // Scroll reveal
  const io = new IntersectionObserver((entries) => {
    entries.forEach((e) => {
      if (e.isIntersecting) {
        e.target.classList.add('in');
        io.unobserve(e.target);
      }
    });
  }, { threshold: 0.12 });
  document.querySelectorAll('.reveal').forEach((el) => io.observe(el));

})();